"""Explain copied lengths, KMSAN metadata notifications and manual read checks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1677': ('책 8쪽을 전달하려 했지만 3쪽이 남았다면 받은 쪽은 5쪽을 받은 것이에요. 검사할 전달 범위도 실제로 넘어간 양에 맞춰야 해요.', '사용자 전달의 요청 길이·남은 길이·실제 길이를 구별합니다.', '커널 from → 사용자 to 화살표를 그리세요. 요청 8, 미복사 left 3, 실제 8-3=5를 각각 적으세요.', ['사용자 공간은 일반 프로그램이 쓰는 영역이고 커널 공간은 운영체제 내부가 사용하는 영역이에요. kmsan_copy_to_user는 커널에서 사용자 쪽으로 데이터를 전달한 사실을 KMSAN에 알리는 인터페이스예요.', 'from은 원본 주소, to는 목적지 주소, to_copy는 복사하려던 길이예요. left는 복사하지 못하고 남은 길이예요. 정상적인 남은 길이는 0 이상 요청 길이 이하로 해석해야 해요.', '요청이 8바이트이고 left가 3이면 실제 전달량은 8-3=5바이트예요. left를 더해 11로 계산하거나 left 자체를 전달량 3으로 읽으면 틀려요. left가 0이면 전부, 8이면 아무것도 전달되지 않은 경우예요.', '실제 사용자 전달이면 이미 복사된 범위의 초기화 상태를 검사해요. 미초기화 데이터에는 의도하지 않은 이전 메모리 내용이 섞일 수 있어 사용자 쪽으로 새어 나가는 문제를 찾으려는 것이에요. 이 알림이 데이터 복사 자체를 대신하지는 않아요.', '구현 주석은 이 시점에 복사가 이미 끝났으며 실제 복사량을 그때 알 수 있다고 설명해요. 따라서 검사 호출을 전달 전에 모든 유출을 막는 차단문으로 이해하면 안 돼요. 활성 검사 경로는 to_copy-left 길이로 검사해요.', '호환 시스템 호출은 서로 다른 실행 형식의 프로그램 요청을 맞춰 처리하는 경로예요. 원문은 이런 경로에서 목적지가 커널 공간으로 판별되는 경우에는 데이터의 초기화 기록인 metadata를 복사한다고 설명해요. 실제 사용자 전달 검사와 이 내부 전달 기록을 구별하세요.'], [('8바이트를 요청했고 left가 3바이트예요. 실제 전달된 양은 얼마인가요?', ['8+3인 11바이트예요', '8-3인 5바이트예요'], '정답은 두 번째예요. left는 아직 복사하지 못한 양이므로 요청에서 빼요. 실제 전달된 5바이트와 남은 3바이트를 합치면 원래 요청 8바이트가 돼요.'), ('호환 경로에서 목적지가 커널 공간으로 판별된 경우 원문은 무엇을 한다고 설명하나요?', ['복사된 범위의 metadata를 옮겨요', '언제나 사용자 정보 유출이라고 보고해요'], '정답은 첫 번째예요. 내부 전달이면 초기화 상태 기록을 이어 주는 경로예요. 사용자에게 실제 전달한 경우의 유출 검사와 목적지 주소 공간에 따른 동작을 나누어 보세요.')]), 'os1678': ('물건을 옮기고 나서 그 물건의 점검 기록도 새 위치로 옮겨야 해요. 기록만 옮겨 놓는다고 물건 자체가 이동하지는 않아요.', '비계측 데이터 복사와 뒤따르는 KMSAN 기록 복사를 구별합니다.', '원본 데이터 → 실제 copy → 목적지 데이터, 원본 초기화 기록 → kmsan_memmove → 목적지 기록을 두 줄로 그리세요.', ['컴파일러는 일반 코드의 메모리 접근에 검사 코드를 붙일 수 있어요. 하지만 어셈블리처럼 자동 계측이 보지 못하는 방식으로 데이터를 옮기는 경우가 있어요. 비계측은 그런 검사 연결이 붙지 않았다는 뜻이에요.', 'kmsan_memmove는 비계측 memmove나 memcpy가 실제 데이터를 옮긴 뒤 호출하는 알림이에요. memmove와 memcpy는 실제 데이터 복사 함수이고, 앞에 kmsan이 붙은 이 인터페이스는 검사 기록을 맞추는 역할이에요.', 'metadata는 데이터를 설명하는 부가 정보예요. 여기서는 원본의 어느 부분이 초기화되었는지 같은 기록을 목적지에도 이어 줘야 해요. 실제 내용만 바뀌고 기록은 옛 상태로 남으면 검사기가 잘못 판단할 수 있어요.', '예를 들어 원본 4칸 중 처음 3칸만 초기화되어 있다면 실제 복사 뒤 목적지에도 그 상태를 맞춰야 해요. 복사했다는 이유만으로 네 칸 모두 초기화됐다고 표시하면 미초기화 한 칸을 놓칠 수 있어요.', 'to는 목적지, from은 원본, to_copy는 기록을 반영할 길이예요. 데이터가 실제로 이동한 범위와 기록을 옮기는 범위를 맞춰야 해요. 이 알림만 호출하고 실제 복사를 빼먹으면 목적지의 실제 데이터가 원하는 값이 되지 않아요.', '따라서 순서는 실제 비계측 복사 → metadata 알림이에요. 이 수업은 그 인터페이스의 목적과 순서를 읽어요. 호출 인자를 기록하는 작은 모델과 실제 shadow라는 상태 저장 영역의 복사 알고리즘을 실행하는 검사는 별도예요.'], [('kmsan_memmove 알림은 비계측 실제 복사의 앞에 두나요, 뒤에 두나요?', ['항상 실제 복사 앞에 둬요', '실제 복사 뒤에 둬요'], '정답은 두 번째예요. 헤더는 비계측 memmove/memcpy가 호출된 뒤 metadata를 복사한다고 설명해요. 데이터 이동과 뒤의 상태 기록 반영을 나누어 읽으세요.'), ('kmsan_memmove만 호출하면 실제 데이터 복사도 끝나나요?', ['아니요. 이 인터페이스의 역할은 metadata 반영이에요', '네. 일반 memcpy와 완전히 같아요'], '정답은 첫 번째예요. 실제 데이터는 앞의 복사 연산이 옮겨야 해요. 검사 기록을 옮기는 도구를 데이터 자체를 복사하는 도구로 대신 쓰면 안 돼요.')]), 'os1679': ('점검원이 쉬는 날에도 접수 형식을 유지할 수 있어요. 그런데 아무 지적이 없었다고 모든 항목을 실제로 검사했다고 말할 수는 없어요.', 'KMSAN 비활성 함수와 검사 통과의 차이를 이해합니다.', '활성 선언 다섯 개를 적고 비활성일 때 각각 빈 함수로 이어진다고 표시하세요. 검사 안 함과 검사 통과를 다른 칸에 적으세요.', ['CONFIG_KMSAN은 커널에 KMSAN 기능을 넣을지 정하는 설정이에요. 헤더는 이 설정이 켜진 경우의 함수 선언과 꺼진 경우의 대체 함수를 나눠 제공해요. 코드가 실행될 때 매번 설정을 바꾸는 버튼이 아니에요.', '꺼진 쪽의 poison, unpoison, check, copy_to_user, memmove는 모두 빈 inline 함수예요. 빈 중괄호 안에는 초기화 기록 변경이나 오류 보고를 실행하는 문장이 없어요.', '같은 함수 이름을 제공하면 기능을 사용하는 코드가 설정마다 별도의 호출 형식을 만들 필요를 줄일 수 있어요. 이런 대체 구현을 stub이라고 해요. 호출 연결을 유지하는 것과 실제 검사 기능을 제공하는 것은 달라요.', 'kmsan_check_memory의 빈 구현을 호출해도 버퍼를 0으로 채우지 않아요. poison과 unpoison의 빈 구현도 실제 데이터를 만들지 않아요. 데이터 초기화는 실제 데이터 쓰기 코드가 담당해야 해요.', '빈 함수이므로 인자의 부수 효과는 C 규칙에 따라 평가돼요. 예를 들어 주소를 준비하는 함수가 실행 횟수를 늘린다면 본문이 비었다고 그 효과가 무조건 사라지지는 않아요. 인자를 치환 결과에서 버리는 빈 매크로와 구별하세요.', '이 구성에서 경고가 없다는 것은 초기화 검증이 끝났다는 증거가 아니에요. 검사 기능을 실행하지 않았기 때문일 수 있어요. 결과를 적을 때 설정, 실제 선택된 함수, 확인한 범위를 함께 적어야 해요.'], [('CONFIG_KMSAN이 꺼진 경우 kmsan_check_memory의 본문은 무엇인가요?', ['버퍼 전체를 0으로 채우는 코드예요', '비어 있는 inline 함수예요'], '정답은 두 번째예요. else 분기의 본문에는 동작이 없어요. 검사 엔진도 데이터 초기화도 수행하지 않으며 설정과 무관한 호출 형식을 유지하는 역할이에요.'), ('KMSAN이 꺼진 실행에서 경고가 없으면 초기화 검사가 완료된 것인가요?', ['아니요. 검사 기능이 꺼져 있으므로 그렇게 판단할 수 없어요', '네. 모든 원본 바이트를 검증한 결과예요'], '정답은 첫 번째예요. 검사하지 않아서 보고가 없는 것과 검사해서 조건을 확인한 것은 달라요. 빈 대체 구현의 실행을 실제 검사 통과로 기록하면 안 돼요.')]), 'os1680': ('자동 점검기가 볼 수 없는 통로라면 그 통로를 지나기 전에 직접 점검 요청을 넣을 수 있어요. 점검 요청과 실제 통로를 지나는 동작은 별개예요.', '수동 읽기 계측의 호출 순서와 실제 읽기를 구별합니다.', 'instrument_read: KASAN 읽기 검사 → KCSAN 읽기 검사 → 바깥의 실제 데이터 읽기를 그리세요.', ['계측은 프로그램이 무슨 접근을 하는지 검사 도구가 알도록 코드를 붙이는 일이에요. instrumented.h는 컴파일러가 자동으로 계측하기 어려운 접근에 수동으로 검사 연결을 넣는 도우미들을 제공해요.', '예를 들어 어셈블리로 만든 특별한 읽기 경로에서는 일반 C 코드처럼 자동 검사가 붙지 않을 수 있어요. 이럴 때 실제 접근을 수행하는 코드와 그 접근을 알려 줄 도우미를 맞춰 연결해야 해요.', 'instrument_read(v, size)는 대상 주소 v와 읽을 크기 size를 받아요. 먼저 kasan_check_read(v, size), 그 다음 kcsan_check_read(v, size)를 호출해요. 같은 주소·크기라도 두 도구가 살피는 질문은 달라요.', 'KASAN은 접근할 범위와 메모리 수명의 유효성 문제를 찾고, KCSAN은 동시 접근 충돌을 살펴요. 헤더 전체가 KMSAN 관련 도우미도 제공하지만 이 instrument_read 본문은 이 두 호출이에요. 모든 도우미가 세 검사를 전부 호출한다고 외우면 안 돼요.', '문서는 instrument_read를 실제 읽기 전에 넣으라고 해요. 이후 데이터 값을 얻는 실제 읽기는 별도의 연산이 수행해요. 이 함수의 반환형은 void라서 대상에 있던 숫자를 호출자에게 돌려주는 읽기 함수가 아니에요.', '또 이 도우미를 호출했다고 잠금을 잡는 것은 아니에요. 설정에 따라 각 검사 호출은 빈 구현일 수 있어요. 실제 읽기의 주소·범위·수명·동기화는 올바르게 준비하고, 검사 연결과 데이터 동작을 따로 따라가세요.'], [('instrument_read 본문의 두 검사 호출 순서는 무엇인가요?', ['KMSAN 데이터 복사 호출 하나뿐이에요', 'KASAN 읽기 검사 뒤 KCSAN 읽기 검사예요'], '정답은 두 번째예요. 원문 본문은 kasan_check_read 다음 kcsan_check_read예요. 이 도우미가 직접 데이터를 복사하거나 대상 숫자를 반환하는 것은 아니에요.'), ('instrument_read는 실제 데이터 읽기 전에 넣나요?', ['네. 실제 읽기 전에 넣어요', '아니요. 언제나 읽기가 모두 끝난 뒤만 넣어요'], '정답은 첫 번째예요. kernel-doc은 before the actual read happens라고 설명해요. 실제 복사 뒤 상태 기록을 옮기는 kmsan_memmove와 역할·위치가 다르다는 점을 비교하세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_415.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
